        &=& 0 &&\\
        \end{array}
\end{displaymath}
using the HYM condition $\hat{F}_{A}=0$ and  $\omega
\wedge \omega =\frac{\left( cst.\right) }{\left\Vert \omega \right\Vert ^{2}}
\ast \omega $.
\end{proof}

