      \label{Def space of Hermitian bundle metrics}
Let $\mathcal{H}_{0}$ be the set of smooth Hermitian metrics $H$ on $\mathcal{E}\rightarrow W$ such that:
\begin{displaymath}
\fbox{$
\begin{array}{c}
        H \overset{C^\infty}{\underset{S\rightarrow\infty}{\longrightarrow}} H_0. \\
\end{array}
$} 
\end{displaymath}

\begin{remark}       \label{Rem All about H0}
About the \emph{Definition}:
\begin{list}{\labelitemi}{\leftmargin=0em}
        \item[(1)] 
        The exponential decay $\left(\ref{Eq (e hat)0 decays exp}\right)$ implies $H_{0}\in \mathcal{H}_{0}$. Indeed, $\mathcal{H}_{0}$ is a \emph{star domain} in the affine space $H_0+\mathcal{I}_0$, in the sense that $H_{0}+\ell\left( H-H_{0} \right)\in \mathcal{H}_0$, $\forall\left(\ell,H\right)\in[0,1]\times \mathcal{H}_0$, with $H-H_{0}\in \mathcal{I}_0$. Thus $\mathcal{H}_{0}$ is contractible, hence \emph{connected} and \emph{simply connected}.

        \item[(2)] 
There is a well-defined notion of `infinitesimal variation' of a metric $H$, as an object in the `tangent space'
        \begin{equation*}
                T_{H}\mathcal{H}_{0}\simeq \mathcal{I}_{0}.
        \end{equation*}

        \item[(3)]
We know from $(\ref{Eq (e hat)0 decays exp})$ that $\hat{F}_{H_0} \overset{C^0}{\underset{S\rightarrow\infty}{\longrightarrow}} 0$, hence \emph{Lemma \ref{Lemma 1st order var of curvature}} implies
\begin{displaymath}
        \left\Vert \hat{F}_{H}\right\Vert _{L^{1}\left( W,\omega\right)}
        <\infty, \quad\forall H \in\mathcal{H}_0.
\end{displaymath}
        \item[(4)] 
Any `nearby' $H\in \mathcal{H}_{0}$, for which $\xi =\log H_{0}^{-1}H$ is well-defined (i.e.,  $\Vert H_{0}^{-1}H-I\Vert_{C^{0}(W,\omega)}<1$), is joined to $H_{0}$ by 
\begin{equation}        \label{eq def path in H0}
\begin{array}{c}
        \gamma :\left[ 0,1\right] \rightarrow \mathcal{H}_{0} \\ 
        \gamma \left( \ell \right) =H_{0}\e{\ell \xi }
\end{array}.
\end{equation}
Clearly $\ell\xi \overset{C^\infty}{\underset{S\rightarrow\infty}{\longrightarrow}} 0$, so $\gamma(\ell)\in \mathcal{H}_0$, $\forall\ell \in [0,1]$.
        \item[(5)] 
        Given any $T>0$, the solutions $\left\{ H_{t}\right\} _{t\in \left[0,T\right] }$ of our flow form a path in $\mathcal{H}_{0}$
, since $\hat{F}_{H_{t}}$ decays exponentially along
the tube for each  $t$ [\emph{Theorem \ref{thm sols for all time and exponentially decaying}}].
\end{list}
\end{remark}

