tr}\left( \tau .\frac{\partial \sigma }{\partial \bar{z}}d\bar{z}+\left( \left(\partial_{H}\tau \right)_{z} .\sigma dz\right)\wedge \left( \kappa _{I}^{2}+O\left( \e{-S}\right) \right) \right) \\
