         \label{Thm MAIN THEOREM}
Let $\mc{E}\rightarrow W$ be stable at
infinity [cf. \emph{Definition \ref{def bundle E->W}}], equipped with a reference metric $H_{0}$ [cf. Definition \ref{def reference metric H0}], over an asymptotically
cylindrical $SU\left( 3\right) -$manifold $W$ as given by the
Calabi-Yau-Tian-Kovalev \emph{Theorem \ref{Thm SU(3) mfds}}, and let $\left\{
H_{t}=H_{0}e^{\xi _{t}}\right\} $ be the $1-$parameter family of Hermitian
metrics on $\mathcal{E}$ given by \emph{Theorem \ref{thm sols for all time and exponentially decaying}}; the limit $H=\lim\limits_{t\rightarrow\infty}H_t$ exists and is a smooth Hermitian Yang-Mills metric on  $\mathcal{E}$, exponentially asymptotic  in all derivatives [cf. \emph{Notation \ref{Not finite cylinder}}] to $H_0$ along the tubular end of $W$: 
\index{asymptotic decay!of HYM metric}
\begin{equation*}       \index{metric!Hermitian Yang-Mills}
\fbox{$\begin{array}{c}
        \hat{F}_{H}=0, \quad H \overset{C^\infty}{\underset{S\rightarrow\infty}{\longrightarrow}} H_0. \\
\end{array}$}
\end{equation*}

\begin{equation*}       \index{metric!Hermitian Yang-Mills}
\fbox{$\begin{array}{c}
        \hat{F}_{H}=0, \quad H \overset{C^\infty}{\underset{S\rightarrow\infty}{\longrightarrow}} H_0. \\
\end{array}$}
\end{equation*}

It is fair to ask whether there are any holomorphic bundles at all satisfying
the asymptotic stability conditions of \emph{Definition \ref{def bundle E->W}
}, thus providing concrete\emph{\ }instances for  \emph{Theorem \ref{Thm MAIN THEOREM}}.

Those are called \emph{instanton monads} and have the form
\begin{equation}        \label{eq instanton monad}
\begin{array}{ccccccccc}
0 & \rightarrow & \mathcal{O}_X\left(-1\right)^{\oplus c} & \overset{\alpha}{\longrightarrow} & \mathcal{O}_X^{\oplus2+2c} & \overset{\beta}{\longrightarrow} & \mathcal{O}_X\left(1\right)^{\oplus c} & \rightarrow & 0.\\
\end{array}
\end{equation}

\begin{equation}        \label{eq instanton monad}
\begin{array}{ccccccccc}
0 & \rightarrow & \mathcal{O}_X\left(-1\right)^{\oplus c} & \overset{\alpha}{\longrightarrow} & \mathcal{O}_X^{\oplus2+2c} & \overset{\beta}{\longrightarrow} & \mathcal{O}_X\left(1\right)^{\oplus c} & \rightarrow & 0.\\
\end{array}
\end{equation}

Loosely speaking, the asymptotically cylindrical  $G_{2}-$structures on certain `matching' pairs $W'\times S^1$ and $W''\times S^1$ are superposed along a truncated gluing region down the tubular ends, using cut-off functions to yield a global 
$G_{2}-$structure $\varphi $ on the compact manifold 
\begin{displaymath}
        M_S:= W'\tilde\#_S W'',
\end{displaymath}
defined by a certain `twisted' gluing procedure.

\label{Lemma integration by parts on W}

Let $X^{n}\subseteq W$ be a compact complex (sub)manifold (possibly $n=3$), $\Phi $ a $\left( 1,1\right)-$form, $\Omega $ a closed $\left( n-2,n-2\right) -$form and $f$ a
meromorphic function on $X$; then 
\begin{equation*}
        \int_{X}
        \Phi \wedge dd^{c}f\wedge \Omega 
        =\int_{X}
        f.\left( -\mathbf{i}\bar{\partial}\partial \Phi \right) \wedge \Omega         +\mathbf{i}\int_{\partial X}
        \left( \Phi \wedge \bar{\partial}f+f.\partial \Phi \right)\wedge\Omega.
\end{equation*}
\begin{proof}
By the Leibniz rule and Stokes' theorem, using $d=\partial +\bar{\partial}$
and taking account of bi-degree, we have
\begin{eqnarray*}
\int_{X}\Phi \wedge dd^{c}f\wedge \Omega &=&\int_{X}\Phi \wedge \mathbf{i}
\partial \bar{\partial}f\wedge \Omega \\
&=&\mathbf{i}\int_{\partial X}\Phi \wedge \bar{\partial}f\wedge \Omega 
\underset{\left( \ast \right) }{\underbrace{-\int_{X}\mathbf{i}\partial \Phi
\wedge \bar{\partial}f\wedge \Omega }}
\end{eqnarray*}
and again
\begin{eqnarray*}
\left( \ast \right) &=&\mathbf{i}\int_{\partial X}f.\partial \Phi \wedge
\Omega +\int_{X}f.\left( -\mathbf{i}\bar{\partial}\partial \Phi \right)
\wedge \Omega .
\end{eqnarray*}
\vspace{-1.3cm}\[\qedhere\]
\end{proof}

